begin;
do $$
declare a uuid:=gen_random_uuid();s uuid:=gen_random_uuid();other_s uuid:=gen_random_uuid();p uuid:=gen_random_uuid();v uuid:=gen_random_uuid();loc uuid;
d1 uuid:=gen_random_uuid();d2 uuid:=gen_random_uuid();d3 uuid:=gen_random_uuid();sale1 uuid:=gen_random_uuid();sale2 uuid:=gen_random_uuid();old_sale uuid:=gen_random_uuid();other_sale uuid:=gen_random_uuid();reservation uuid:=gen_random_uuid();item uuid;j jsonb;today date:=(now() at time zone 'America/Monterrey')::date;baseline jsonb;legacy uuid:=gen_random_uuid();empty_role uuid:=gen_random_uuid();blocked boolean;
begin
 insert into auth.users(id,email) values(a,a::text||'@example.invalid'),(s,s::text||'@example.invalid'),(other_s,other_s::text||'@example.invalid');
 update arma_private.user_security set requires_password_change=false,sessions_valid_from=null where user_id in(a,s,other_s);
 insert into public.user_roles(user_id,role_id) select a,id from public.roles where code='admin' on conflict do nothing;
 insert into public.user_roles(user_id,role_id) select u.id,r.id from (values(s),(other_s))u(id) cross join public.roles r where r.code='seller' on conflict do nothing;
 insert into public.products(id,code,name,created_by) values(p,p::text,'TEST SEPARATE HOME',a);
 insert into public.product_variants(id,product_id,sku,size,color,sale_price) values(v,p,v::text,'M','Negro',300);
 select id into loc from public.inventory_locations where is_default and is_active;
 insert into public.inventory_balances(location_id,product_variant_id,physical_quantity,average_unit_cost) values(loc,v,30,100);
 execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 baseline:=public.business_dashboard(today,today);
 perform public.seller_write(jsonb_build_object('request_id',d1,'action','deliver','seller_id',s,'variant_id',v,'quantity',6,'unit_price',200));
 perform public.seller_write(jsonb_build_object('request_id',d2,'action','deliver','seller_id',s,'variant_id',v,'quantity',2,'unit_price',220));
 perform public.seller_write(jsonb_build_object('request_id',d3,'action','deliver','seller_id',other_s,'variant_id',v,'quantity',1,'unit_price',180));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'role','authenticated')::text,true);
 perform public.create_commerce_order(jsonb_build_object('request_id',sale1,'kind','sale','variant_id',v,'delivery_id',d1,'quantity',4,'unit_price',300,'payment_method','cash'));
 j:=public.business_dashboard(today,today);
 if j->>'mode'<>'personal' or j->'company'<>'null'::jsonb or (j->'personal'->>'profit')::numeric<>400 or (j->>'sales')::numeric<>1200 or (j->>'sale_count')::int<>1 then raise exception '1200 sales / 400 seller profit not separated: %',j;end if;
 perform public.create_commerce_order(jsonb_build_object('request_id',old_sale,'kind','sale','variant_id',v,'delivery_id',d1,'quantity',1,'unit_price',300,'payment_method','cash'));
 execute 'reset role';update public.commerce_orders set created_at=(today-1+time '12:00') at time zone 'America/Monterrey' where id=old_sale;update arma_private.commerce_payments set created_at=(today-1+time '12:00') at time zone 'America/Monterrey' where order_id=old_sale;execute 'set local role authenticated';
 perform public.create_commerce_order(jsonb_build_object('request_id',reservation,'kind','reservation','variant_id',v,'delivery_id',d1,'quantity',1,'unit_price',300,'deposit',150,'customer_name','TEST INITIAL PAYMENT','payment_method','transfer'));
 j:=public.business_dashboard(today,today);
 if (j->'personal'->>'profit')::numeric<>400 or (j->>'receipts')::numeric<>1350 or (j->'personal'->'previous'->>'profit')::numeric<>100 or (j->'personal'->'previous'->>'sale_count')::int<>1 then raise exception 'Period, initial payment or prior comparison incorrect: %',j;end if;
 perform public.create_commerce_order(jsonb_build_object('request_id',sale2,'kind','sale','variant_id',v,'delivery_id',d2,'quantity',1,'unit_price',350,'payment_method','card'));
 j:=public.business_dashboard(today,today);if (j->'personal'->>'profit')::numeric<>530 then raise exception 'Used catalog/current lot cost instead of 200/220 agreements';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',other_s,'role','authenticated')::text,true);
 perform public.create_commerce_order(jsonb_build_object('request_id',other_sale,'kind','sale','variant_id',v,'delivery_id',d3,'quantity',1,'unit_price',999,'payment_method','cash'));
 j:=public.business_dashboard(today,today);if (j->'personal'->>'profit')::numeric<>819 or (j->>'sales')::numeric<>999 then raise exception 'Other seller sees foreign sales';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 execute 'reset role';select id into item from public.commerce_order_items where order_id=sale1;execute 'set local role authenticated';
 perform public.commerce_adjust('return',jsonb_build_object('request_id',gen_random_uuid(),'order_id',sale1,'item_id',item,'quantity',1,'amount',300,'method','cash','restock',true,'reason','TEST PARTIAL RETURN'));
 j:=public.business_dashboard(today,today);
 if j->>'mode'<>'business' or j->'personal'<>'null'::jsonb or (j->>'sales')::numeric-(baseline->>'sales')::numeric<>2549 or (j->'company'->>'known_margin')::numeric-(baseline->'company'->>'known_margin')::numeric<>500 then raise exception 'Business totals incorrect: %',j;end if;
 if (j->'company'->'series'->0->>'margin')::numeric<>(j->'company'->>'known_margin')::numeric then raise exception 'Company chart disagrees with totals';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',s,'role','authenticated')::text,true);
 j:=public.business_dashboard(today,today);
 if (j->'personal'->>'profit')::numeric<>430 or (j->'personal'->'series'->0->>'profit')::numeric<>430 or (j->>'sale_count')::int<>2 or (j->>'net_receipts')::numeric<>1400 then raise exception 'Personal returns/chart/cash incorrect: %',j;end if;
 j:=public.business_dashboard(today+2,today+4);if (j->'personal'->>'profit')::numeric<>0 or (j->>'sale_count')::int<>0 or jsonb_array_length(j->'personal'->'series')<>3 then raise exception 'Empty period incorrect';end if;
 -- Legacy operation without assigned merchandise must not invent a personal gain from manufacturing cost.
 execute 'reset role';
 insert into public.commerce_orders(id,kind,status,total,deposit,payment_method,created_by,seller_name) values(legacy,'sale','completed',300,0,'cash',s,'TEST LEGACY');
 insert into public.commerce_order_items(order_id,product_variant_id,inventory_balance_id,product_id,product_name,sku,size,color,quantity,catalog_price,unit_price) select legacy,v,b.id,p,'TEST LEGACY',v::text,'M','Negro',1,300,300 from public.inventory_balances b where b.location_id=loc and b.product_variant_id=v;
 execute 'set local role authenticated';
 j:=public.business_dashboard(today,today);if (j->'personal'->>'profit')::numeric<>430 or (j->'personal'->>'unknown_pieces')::int<>1 then raise exception 'Legacy personal profit invented';end if;
 execute 'reset role';insert into public.roles(id,code,name) values(empty_role,'test_'||replace(empty_role::text,'-',''),'TEST NO SALES');delete from public.user_roles where user_id=other_s;insert into public.user_roles(user_id,role_id) values(other_s,empty_role);execute 'set local role authenticated';perform set_config('request.jwt.claims',jsonb_build_object('sub',other_s,'role','authenticated')::text,true);
 j:=public.business_dashboard(today,today);if j->'personal'->'profit'<>'null'::jsonb or (j->>'sales')::numeric<>0 then raise exception 'Role without sales permission sees profit';end if;
 blocked:=false;begin perform arma_private.company_finances(now()-interval '1 day',now());exception when insufficient_privilege then blocked:=true;end;if not blocked then raise exception 'Personal user can call company finances directly';end if;
end;$$;
rollback;
